public class Frequency_addValue_TriageGen0Test {

    private Frequency frequency;

    @Before
    public void setUp() {
        frequency = new Frequency();
    }









    @Test
    public void testAddValue_IntegerAndLongConsistency() {
        // The implementation converts Integer to Long, so they should be treated as the same key
        frequency.addValue(10); // Integer -> Long 10L
        frequency.addValue(10L); // Long 10L
        assertEquals(2L, frequency.getCount(10L));
    }








