public class Frequency_addValue_TriageGen0Test {

    private Frequency frequency;

    @Before
    public void setUp() {
        frequency = new Frequency();
    }













    @Test(expected = IllegalArgumentException.class)
    public void testAddValue_IncompatibleTypes() {
        // Add a Long first
        frequency.addValue(10L);
        // Adding a String will cause ClassCastException in TreeMap, 
        // which should be caught and rethrown as IllegalArgumentException
        frequency.addValue("incompatible");
    }




}

