import static org.junit.Assert.*;

/**
 * Unit tests for org.apache.commons.math.stat.Frequency#addValue(Object)
 */
public class Frequency_addValue_TriageGen0Test {

    private Frequency frequency;

    @Before
    public void setUp() {
        frequency = new Frequency();
    }















    @Test
    public void testAddValue_MultipleDifferentValues() {
        frequency.addValue(1L);
        frequency.addValue(2L);
        frequency.addValue(1L);
        frequency.addValue("a");

        assertEquals(2L, frequency.getCount(1L));
        assertEquals(1L, frequency.getCount(2L));
        assertEquals(1L, frequency.getCount("a"));
        assertEquals(4L, frequency.getSumFreq());
    }


}

